});

/* ---------- approval ---------- */
approvalCard.querySelectorAll('[data-decision]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    var decision = btn.getAttribute('data-decision');
    approvalPending = false;
    approvalCard.classList.add('is-resolved');
    if (decision === 'approve') {
      approvalStatus.textContent = '已批准';
      approvalStatus.className = 'status-chip is-ok';
      resolvedText.textContent = '已批准，主智能体已恢复运行，正在调用 Slack MCP。';
      runStatus.className = 'status-chip is-live';
      runDot.className = 'dot is-live';
      runStatusText.textContent = '运行中';
      sessionStateText.textContent = '运行中';
      sessionStateDot.className = 'dot is-live';
      setTrajRunState('running');
      setTrajApprovalState('approved');
      setRunViewStatus('running');
      if (finalWaitNote) {
        finalWaitNote.className = 'final-wait';
        finalWaitNote.innerHTML = '<svg class="ic" aria-hidden="true"><use href="#i-shield"/></svg>已批准，正在发布到 #support-weekly…';
      }
      showToast('已批准，主智能体继续执行');
      completeTimer = setTimeout(function () {
        completeTimer = null;
        runActive = false;
        runStatus.className = 'status-chip is-ok';
        runDot.className = 'dot is-ok';
        runStatusText.textContent = '已完成';
        resolvedText.textContent = '已批准，Slack 消息已发布。';
        sessionStateText.textContent = '已完成';
        sessionStateDot.className = 'dot is-ok';
        usageLabel.textContent = '本轮';
        setTrajRunState('done');
        setTrajApprovalState('sent');
        setRunViewStatus('done');
        if (finalWaitNote) {
          finalWaitNote.className = 'final-wait is-done';
          finalWaitNote.innerHTML = '<svg class="ic" aria-hidden="true"><use href="#i-check"/></svg>已发布到 #support-weekly · 可在 Slack 中删除';
        }
        if (trajApprovalSeg) {
          trajApprovalSeg.classList.remove('is-rejected');
          trajApprovalSeg.classList.add('is-done');
        }
        updateTrackOutcome('MCP · Slack 已发送', true);
        updateSendState();
        showToast('本轮运行已完成，可以继续对话');
      }, 1800);
    } else {
      approvalCard.classList.add('is-rejected');
      approvalStatus.textContent = '已拒绝';
      approvalStatus.className = 'status-chip';
      resolvedText.textContent = '已拒绝，本轮运行已取消。';
      runStatus.className = 'status-chip';
      runDot.className = 'dot';
      runStatusText.textContent = '已取消';
      sessionStateText.textContent = '已取消';
      sessionStateDot.className = 'dot';
      runActive = false;
      setTrajRunState('rejected');
      setTrajApprovalState('rejected');
      setRunViewStatus('rejected');
      if (finalWaitNote) {
        finalWaitNote.className = 'final-wait is-error';
        finalWaitNote.innerHTML = '<svg class="ic" aria-hidden="true"><use href="#i-x"/></svg>已拒绝发布，本轮已取消';
      }
      if (trajApprovalSeg) trajApprovalSeg.classList.add('is-rejected');
      updateTrackOutcome('已取消 · Slack 发送', false);
      markTrackCanceled();
      showToast('已拒绝，本轮运行已取消');
    }
    updateSendState();
  });
});

function stopRun() {
  if (!runActive && !approvalPending) return;
  runActive = false;
  approvalPending = false;
  if (completeTimer) {
    clearTimeout(completeTimer);
    completeTimer = null;
  }
  approvalCard.classList.add('is-resolved', 'is-rejected');
  approvalStatus.textContent = '已取消';
  approvalStatus.className = 'status-chip';
  resolvedText.textContent = '本轮已停止，Slack 发布未执行。';
  runStatus.className = 'status-chip';
  runDot.className = 'dot';
  runStatusText.textContent = '已取消';
  sessionStateText.textContent = '已取消';
  sessionStateDot.className = 'dot';
  setTrajRunState('rejected');
  setTrajApprovalState('canceled');
  setRunViewStatus('rejected');
  if (finalWaitNote) {
    finalWaitNote.className = 'final-wait is-error';
    finalWaitNote.innerHTML = '<svg class="ic" aria-hidden="true"><use href="#i-x"/></svg>本轮已停止，未发布到 Slack';
  }
  if (trajApprovalSeg) trajApprovalSeg.classList.add('is-rejected');
  updateTrackOutcome('已取消 · Slack 发送', false);
  markTrackCanceled();
  updateSendState();
  showToast('本轮运行已停止');
}

runStatus.addEventListener('click', function () {
  if (!approvalPending) return;
