});

/* ---------- workflow context + model controls ---------- */
function escComposer(value) {
  return String(value).replace(/[&<>"']/g, function (ch) {
    return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch];
  });
}

function openComposerMenu() {
  closeModelMenu();
  composerMenu.hidden = false;
  composerPlus.setAttribute('aria-expanded', 'true');
}

function closeComposerMenu() {
  composerMenu.hidden = true;
  composerPlus.setAttribute('aria-expanded', 'false');
}

function openModelMenu() {
  closeComposerMenu();
  modelMenu.hidden = false;
  modelBtn.setAttribute('aria-expanded', 'true');
}

function closeModelMenu() {
  modelMenu.hidden = true;

    btn.addEventListener('click', function () {
      if (btn.disabled) return;
      selectWorkflow(btn.getAttribute('data-workflow'), true);
    });
  });

  document.querySelectorAll('[data-knowledge]').forEach(function (btn) {
