function renderComposerContext() {
  var html = '';
  var count = 0;

  if (selectedWorkflow) {
    var wf = CHAT_WORKFLOWS[selectedWorkflow];
    html += '<span class="ctx-chip ctx-workflow">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-workflow"/></svg>' +
      escComposer(wf.name) +
      '<small>' + wf.steps.length + ' 步</small>' +
      '<button class="ctx-remove" data-remove="workflow" aria-label="移除工作流"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>' +
    '</span>';
    count += 1;
  }

  selectedSkills.forEach(function (id) {
    html += '<span class="ctx-chip ctx-skill">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-stack"/></svg>' +
      escComposer(id) +
      '<button class="ctx-remove" data-remove="skill" data-value="' + escComposer(id) + '" aria-label="移除技能"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>' +
    '</span>';
    count += 1;
  });

  if (knowledgeSelected) {
    html += '<span class="ctx-chip ctx-knowledge">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-db"/></svg>' +
      'support-kb' +
      '<button class="ctx-remove" data-remove="knowledge" aria-label="移除知识库"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>' +
    '</span>';
    count += 1;
  }

  selectedMcp.forEach(function (id) {
    html += '<span class="ctx-chip ctx-mcp">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-stack"/></svg>' +
      escComposer(id) +
      '<button class="ctx-remove" data-remove="mcp" data-value="' + escComposer(id) + '" aria-label="移除 MCP 服务器"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>' +
    '</span>';
    count += 1;
  });

  attachedFiles.forEach(function (name, index) {
    html += '<span class="ctx-chip ctx-file">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-clip"/></svg>' +
      escComposer(name) +
      '<button class="ctx-remove" data-remove="file" data-index="' + index + '" aria-label="移除附件"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>' +
    '</span>';
    count += 1;
  });

  composerContext.innerHTML = html;
