            '<div class="wf-name">' + escWf(wf.name) + ' <span class="tag">' + escWf(wf.version) + '</span></div>' +
            '<p class="wf-desc">' + escWf(wf.desc) + '</p>' +
          '</div>' +
          '<div class="wf-state">' +
            '<button class="wf-switch' + (wf.enabled ? ' is-on' : '') + '" data-wf-toggle role="switch" aria-checked="' + String(wf.enabled) + '" aria-label="' + (wf.enabled ? '停用' : '启用') + escWf(wf.name) + '"><span></span></button>' +
            '<span class="wf-state-text">' + (wf.enabled ? '启用' : '草稿') + '</span>' +
          '</div>' +
        '</div>' +
        '<div class="wf-route"><div class="wf-route-label">执行轨迹</div><div class="wf-steps">' + workflowStepsHTML(wf) + '</div></div>' +
        '<div class="wf-meta"><span>' + wf.steps.length + ' 步</span><span>·</span><span>' + a2aCount + ' 个远程智能体</span><span>·</span><span>' + approvalCount + ' 个审批</span><span>·</span><span>运行 ' + wf.runs + ' 次</span><span class="spacer"></span><span>更新于 ' + escWf(wf.updated) + '</span></div>' +
        '<div class="wf-actions">' + useAction +
          '<button class="btn btn-outline btn-sm" data-wf-edit>编辑</button>' +
          '<button class="btn btn-ghost btn-sm" data-wf-copy>复制</button>' +
          '<span class="spacer"></span>' +
          '<button class="btn btn-ghost btn-sm is-danger-text" data-wf-delete>删除</button>' +
        '</div>' +
      '</article>';
    }).join('');

    workflowEmpty.hidden = WORKFLOWS.length > 0;
    var enabledCount = WORKFLOWS.filter(function (wf) { return wf.enabled; }).length;
    var totalSteps = WORKFLOWS.reduce(function (sum, wf) { return sum + wf.steps.length; }, 0);
    wfStatTotal.textContent = String(WORKFLOWS.length);
    wfStatEnabled.textContent = String(enabledCount);
    wfStatDraft.textContent = String(WORKFLOWS.length - enabledCount);
    wfStatSteps.textContent = String(WORKFLOWS.length ? Math.round(totalSteps / WORKFLOWS.length) : 0);
  }

  workflowList.addEventListener('click', function (event) {
    var card = event.target.closest('.wf-card');
    if (!card) return;
    var id = card.getAttribute('data-wf-id');
    var wf = findWorkflow(id);
    if (!wf) return;
    if (event.target.closest('[data-wf-toggle]')) {
      wf.enabled = !wf.enabled;
      renderWorkflows();
      showToast(wf.enabled ? '已启用「' + wf.name + '」' : '已停用「' + wf.name + '」');
      return;
    }
    if (event.target.closest('[data-wf-edit]')) {
      openWorkflowEditor(id);
      return;
    }
    if (event.target.closest('[data-wf-copy]')) {
      var copy = JSON.parse(JSON.stringify(wf));
      copy.id = 'wf-' + Date.now();
      copy.name = wf.name + ' 副本';
      copy.version = 'v1';
      copy.enabled = false;
      copy.runs = 0;
      copy.updated = '今天';
      WORKFLOWS.unshift(copy);
      renderWorkflows();
      showToast('已复制为草稿');
      return;
    }
    if (event.target.closest('[data-wf-delete]')) {
      openConfirm('删除工作流？', '「' + wf.name + '」将被删除，历史运行记录保留；此操作不可撤销。', function () {
        WORKFLOWS = WORKFLOWS.filter(function (item) { return item.id !== id; });
        renderWorkflows();
        showToast('已删除「' + wf.name + '」');
      }, '删除工作流');
    }
  });

  var wfEditor = document.getElementById('wfEditor');
  var wfEditorScrim = document.getElementById('wfEditorScrim');
  var wfEditorTitle = document.getElementById('wfEditorTitle');
  var wfName = document.getElementById('wfName');
  var wfDesc = document.getElementById('wfDesc');
  var wfEditSteps = document.getElementById('wfEditSteps');
  var wfStepCount = document.getElementById('wfStepCount');
  var wfEditorBody = wfEditor ? wfEditor.querySelector('.wf-editor-body') : null;
  var editingWfId = null;
  var editingSteps = [];
  var wfDirty = false;

  function openWorkflowEditor(id) {
    editingWfId = id || null;
    if (id) {
      var wf = findWorkflow(id);
      if (!wf) return;
      wfEditorTitle.textContent = '编辑工作流';
      wfName.value = wf.name;
      wfDesc.value = wf.desc;
      editingSteps = JSON.parse(JSON.stringify(wf.steps));
    } else {
      wfEditorTitle.textContent = '新建工作流';
      wfName.value = '';
      wfDesc.value = '';
      editingSteps = [{ type: 'skill', name: STEP_CATALOG.skill.options[0], approval: false }];
    }
    renderEditSteps();
    wfDirty = false;
    wfEditorScrim.classList.add('is-open');
    wfEditor.classList.add('is-open');
    wfEditor.setAttribute('aria-hidden', 'false');
    wfEditor.focus();
    if (wfEditorBody) wfEditorBody.scrollTop = 0;
  }

  function closeWorkflowEditor() {
    wfEditorScrim.classList.remove('is-open');
    wfEditor.classList.remove('is-open');
    wfEditor.setAttribute('aria-hidden', 'true');
    editingWfId = null;
    editingSteps = [];
    wfDirty = false;
  }

  function requestCloseWorkflowEditor() {
    if (!wfEditor.classList.contains('is-open')) return;
    if (!wfDirty) {
      closeWorkflowEditor();
      return;
    }
    openConfirm('放弃未保存的更改？', '工作流「' + (wfName.value.trim() || '未命名') + '」的修改尚未保存，关闭后将丢失。', closeWorkflowEditor, '放弃更改');
  }

  function stepTypeOptions(selected) {
    return Object.keys(STEP_CATALOG).map(function (type) {
      return '<option value="' + type + '"' + (type === selected ? ' selected' : '') + '>' + STEP_CATALOG[type].label + '</option>';
    }).join('');
  }

  function stepNameOptions(type, selected) {
    var options = STEP_CATALOG[type] ? STEP_CATALOG[type].options.slice() : [];
    if (options.indexOf(selected) === -1) options.unshift(selected);
    return options.map(function (name) {
      return '<option value="' + escWf(name) + '"' + (name === selected ? ' selected' : '') + '>' + escWf(name) + '</option>';
    }).join('');
  }

  function renderEditSteps() {
    wfStepCount.textContent = editingSteps.length + ' 步';
    if (!editingSteps.length) {
      wfEditSteps.innerHTML = '<div class="wf-edit-empty">还没有步骤，从下方添加。</div>';
      return;
    }
    wfEditSteps.innerHTML = editingSteps.map(function (step, index) {
      return '<div class="wf-edit-step" data-index="' + index + '">' +
        '<span class="wf-edit-num">' + String(index + 1).padStart(2, '0') + '</span>' +
        '<div class="wf-edit-fields">' +
          '<div class="wf-edit-line">' +
            '<select class="select wf-type" data-step-field="type">' + stepTypeOptions(step.type) + '</select>' +
            '<select class="select wf-name" data-step-field="name">' + stepNameOptions(step.type, step.name) + '</select>' +
          '</div>' +
          '<label class="wf-edit-approval"><input type="checkbox" data-step-field="approval"' + (step.approval ? ' checked' : '') + '> 写操作需审批</label>' +
        '</div>' +
        '<div class="wf-edit-tools">' +
          '<button class="wf-step-btn" data-step-action="up" aria-label="上移"' + (index === 0 ? ' disabled' : '') + '>↑</button>' +
          '<button class="wf-step-btn" data-step-action="down" aria-label="下移"' + (index === editingSteps.length - 1 ? ' disabled' : '') + '>↓</button>' +
          '<button class="wf-step-btn is-danger" data-step-action="remove" aria-label="删除步骤">×</button>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  if (wfName) wfName.addEventListener('input', function () { wfDirty = true; });
  if (wfDesc) wfDesc.addEventListener('input', function () { wfDirty = true; });

  wfEditSteps.addEventListener('change', function (event) {
    wfDirty = true;
    var target = event.target;
    var row = target.closest('.wf-edit-step');
    if (!row) return;
    var index = Number(row.getAttribute('data-index'));
    var field = target.getAttribute('data-step-field');
    if (!field || !editingSteps[index]) return;
    if (field === 'type') {
      editingSteps[index].type = target.value;
      editingSteps[index].name = STEP_CATALOG[target.value].options[0];
      renderEditSteps();
    } else if (field === 'name') {
      editingSteps[index].name = target.value;
    } else if (field === 'approval') {
      editingSteps[index].approval = target.checked;
    }
  });

  wfEditSteps.addEventListener('click', function (event) {
    var btn = event.target.closest('[data-step-action]');
    if (!btn) return;
    wfDirty = true;
    var row = btn.closest('.wf-edit-step');
    var index = Number(row.getAttribute('data-index'));
    var action = btn.getAttribute('data-step-action');
    if (action === 'remove') {
      editingSteps.splice(index, 1);
    } else if (action === 'up' && index > 0) {
      var prev = editingSteps[index - 1];
      editingSteps[index - 1] = editingSteps[index];
      editingSteps[index] = prev;
    } else if (action === 'down' && index < editingSteps.length - 1) {
      var next = editingSteps[index + 1];
      editingSteps[index + 1] = editingSteps[index];
      editingSteps[index] = next;
    }
    renderEditSteps();
  });

  document.querySelectorAll('[data-add-step]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var type = btn.getAttribute('data-add-step');
      editingSteps.push({ type: type, name: STEP_CATALOG[type].options[0], approval: false });
      wfDirty = true;
      renderEditSteps();
      if (wfEditorBody) wfEditorBody.scrollTop = wfEditorBody.scrollHeight;
    });
  });

  document.getElementById('newWorkflowBtn').addEventListener('click', function () {
    openWorkflowEditor(null);
  });

  document.getElementById('closeWfEditor').addEventListener('click', requestCloseWorkflowEditor);
  document.getElementById('cancelWfEditor').addEventListener('click', requestCloseWorkflowEditor);
  wfEditorScrim.addEventListener('click', requestCloseWorkflowEditor);

  document.getElementById('saveWfEditor').addEventListener('click', function () {
    var name = wfName.value.trim();
    var desc = wfDesc.value.trim();
    if (!name) {
      showToast('请先填写工作流名称');
      wfName.focus();
      return;
    }
    if (!editingSteps.length) {
      showToast('至少添加一个步骤');
      return;
    }
    if (editingWfId) {
      var wf = findWorkflow(editingWfId);
      if (wf) {
        wf.name = name;
        wf.desc = desc;
        wf.steps = JSON.parse(JSON.stringify(editingSteps));
        wf.updated = '今天';
      }
      showToast('工作流已保存');
    } else {
      WORKFLOWS.unshift({
        id: 'wf-' + Date.now(),
        name: name,
        desc: desc,
        version: 'v1',
        enabled: false,
        runs: 0,
        updated: '今天',
        steps: JSON.parse(JSON.stringify(editingSteps))
      });
      showToast('工作流已创建为草稿');
    }
    renderWorkflows();
    closeWorkflowEditor();
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && !confirmDialog.classList.contains('is-open')) requestCloseWorkflowEditor();
  });

  renderWorkflows();

  /* ---------- demo actions ---------- */
  document.querySelectorAll('[data-demo]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      showToast(btn.getAttribute('data-demo'));
    });
  });

  /* ---------- initial page ---------- */
  var hash = window.location.hash.replace('#', '');
  if (pageTitles[hash]) showPage(hash);
  else if (hash.indexOf('settings') === 0) showPage('settings', hash);
  else showPage('agents');
})();
</script>
</body>
</html>

